-- Day 4 (generated by drizzle-kit, then made re-runnable by hand: IF NOT EXISTS, guarded constraints,
-- data fixes and duplicate checks with a clear message). The snapshot (meta/0003_snapshot.json) is the
-- untouched drizzle-kit output, so the next `db:generate` starts from the same schema.
CREATE TABLE IF NOT EXISTS "rate_limit" (
	"id" text PRIMARY KEY NOT NULL,
	"key" text NOT NULL,
	"count" integer NOT NULL,
	"last_request" bigint NOT NULL,
	CONSTRAINT "rate_limit_key_unique" UNIQUE("key")
);
