-- subscriptions.email / payment_method are NOT NULL without a default: add, backfill existing rows
-- (none locally), then set NOT NULL. A subscription whose user no longer exists cannot be renewed.
ALTER TABLE "subscriptions" ADD COLUMN IF NOT EXISTS "email" text;--> statement-breakpoint
UPDATE "subscriptions" AS s SET "email" = u."email" FROM "user" AS u WHERE s."email" IS NULL AND u."id" = s."user_id";--> statement-breakpoint
UPDATE "subscriptions" SET "email" = '', "status" = 'cancelled', "cancelled_at" = coalesce("cancelled_at", now()) WHERE "email" IS NULL;--> statement-breakpoint
