-- Barcodes: whitespace-only means "no barcode"; real duplicates stop the migration with a list to fix
-- in the panel (never silently changed).
UPDATE "product_variants" SET "barcode" = NULL WHERE "barcode" IS NOT NULL AND "barcode" <> '' AND btrim("barcode") = '';--> statement-breakpoint
DO $$
DECLARE dup text;
BEGIN
	SELECT string_agg(format('%s (%s varyant)', d.barcode, d.n), ', ') INTO dup
	FROM (SELECT "barcode", count(*) AS n FROM "product_variants" WHERE "barcode" IS NOT NULL AND "barcode" <> '' GROUP BY "barcode" HAVING count(*) > 1) AS d;
	IF dup IS NOT NULL THEN
		RAISE EXCEPTION 'Aynı barkod birden fazla varyantta kayıtlı: %. Panelden düzeltip migration''ı tekrar çalıştırın. (Duplicate barcodes: fix them first.)', dup;
	END IF;
END $$;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "product_variants_barcode_unique" ON "product_variants" USING btree ("barcode") WHERE "product_variants"."barcode" is not null and "product_variants"."barcode" <> '';--> statement-breakpoint
DO $$
BEGIN
	IF EXISTS (SELECT 1 FROM "reviews" WHERE "user_id" IS NOT NULL GROUP BY "product_id", "user_id" HAVING count(*) > 1)
		OR EXISTS (SELECT 1 FROM "reviews" WHERE "order_id" IS NOT NULL GROUP BY "product_id", "order_id" HAVING count(*) > 1) THEN
		RAISE EXCEPTION 'Aynı ürün için aynı müşteriden ya da siparişten birden fazla yorum var; fazlalarını panelden silip migration''ı tekrar çalıştırın. (Duplicate reviews.)';
	END IF;
END $$;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "reviews_product_user_unique" ON "reviews" USING btree ("product_id","user_id") WHERE "reviews"."user_id" is not null;--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "reviews_product_order_unique" ON "reviews" USING btree ("product_id","order_id") WHERE "reviews"."order_id" is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "orders_subscription_id_index" ON "orders" USING btree ("subscription_id");--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "newsletter_subscribers_confirm_token_hash_unique" ON "newsletter_subscribers" USING btree ("confirm_token_hash") WHERE "newsletter_subscribers"."confirm_token_hash" is not null;--> statement-breakpoint
-- Staff sign in although customer e-mail verification becomes required: every staff account counts as
-- verified (the team service, create-admin and panel-test-user set it on creation from now on).
UPDATE "user" SET "email_verified" = true, "updated_at" = now() WHERE "role" IN ('admin', 'editor', 'staff') AND "email_verified" = false;
